class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        step = 0
        for i, row in enumerate(grid):
            if i % 2 == 0:
                cells = row
            else:
                cells = reversed(row)
            for cell in cells:
                if step % 2 == 0:
                    result.append(cell)
                step += 1
        return result

