class Solution:
    def maxSum(self, nums: List[int]) -> int:
        distinct = set(nums)
        pos_sum = sum(v for v in distinct if v > 0)
        if pos_sum > 0:
            return pos_sum
        # No positive distinct values: must keep at least one element.
        # Taking the largest value gives the best (least negative or zero) sum.
        return max(distinct)

