class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        NEG = -10**18
        prev = [0] * (n + 1)  # row for 0 subarrays: f(i, 0) = 0

        for _ in range(k):
            curr = [NEG] * (n + 1)
            best = NEG
            t = 0
            for i in range(n + 1):
                # Add all t <= i - m (last subarray [t, i) has length >= m)
                limit = i - m
                while t <= limit:
                    if prev[t] != NEG:
                        v = prev[t] - prefix[t]
                        if v > best:
                            best = v
                    t += 1
                # carry: don't use a subarray ending at i
                val = curr[i - 1] if i > 0 else NEG
                # use subarray ending at i
                if best != NEG:
                    cand = prefix[i] + best
                    if cand > val:
                        val = cand
                curr[i] = val
            prev = curr

        return prev[n]

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        x = [ord(c) - 97 for c in s]

        def dist(a, b):
            d = abs(a - b)
            return min(d, 26 - d)

        end_cost = [[0] * 26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                best = 10 ** 9
                for c in range(26):
                    val = dist(a, c) + dist(b, c)
                    if val < best:
                        best = val
                end_cost[a][b] = best

        dp = [[None] * n for _ in range(n)]

        for i in range(n - 1, -1, -1):
            for j in range(i, n):
                if i == j:
                    dp[i][j] = [1] * (k + 1)
                    continue

                e = end_cost[x[i]][x[j]]
                left = dp[i + 1][j]
                right = dp[i][j - 1]
                inner = dp[i + 1][j - 1] if i + 1 <= j - 1 else None

                row = [0] * (k + 1)
                for m in range(k + 1):
                    best = left[m] if left[m] >= right[m] else right[m]
                    if m >= e:
                        cand = 2 if inner is None else inner[m - e] + 2
                        if cand > best:
                            best = cand
                    row[m] = best
                dp[i][j] = row

        return dp[0][n - 1][k]
